## Declare

```ts
import { schema, table, id, text, owner, member, anyOf, serverOnly, files } from 'somewhere/db';

export default schema({
  teams: table({ id: id(), name: text() }, { scope: owner(), client: { read: ['id', 'name'], create: ['name'] } }),
  team_members: table({ id: id(), team_id: text(), user_id: text() }, { scope: serverOnly() }),
}, {
  files: {
    // Only the signed-in uploader sees or touches their files.
    uploads: files({
      path: '/uploads', scope: owner(),
      client: { read: true, upload: true, replace: true, delete: true },
      limits: { maxSize: '25MB', types: ['image/*', 'application/pdf'] },
    }),
    // Team members read and upload; only the uploader replaces or deletes.
    attachments: files({
      path: '/attachments',
      scope: anyOf(owner(), member({ group: 'team_id', membership: 'team_members',
        member_user: 'user_id', member_group: 'team_id', operations: ['read', 'upload'] })),
      client: { read: true, upload: true, replace: true, delete: true },
    }),
    // Anyone may view; only the owner uploads, replaces or deletes.
    avatars: files({ path: '/avatars', scope: owner(), public: true,
      client: { upload: true, replace: true, delete: true }, limits: { maxSize: '2MB', types: ['image/*'] } }),
    // Public, written only by your functions or you.
    assets: files({ path: '/assets', scope: serverOnly(), public: true }),
  },
});
```

- **client** lists the browser operations: `read` (list, metadata, download,
  share links), `upload`, `replace`, `delete`. An operation you do not list
  does not exist in the client and is refused by the platform.
- **scope**: `parent({ table, via })` follows a private row's read and update
  access, including built-in group rules. `owner()`: the uploader only.
  `member({ group, membership, member_user, member_group, operations })`:
  members of the file's group; `operations` takes `read`, `upload`,
  `replace`, `delete` (replace/delete need read) and defaults to every
  declared operation. `anyOf(owner(), member(...))`: members, or the
  uploader while in the file's group (team files belong to the team).
  `shared()`: every signed-in user reads, only the uploader replaces or
  deletes. `serverOnly()`: no browser operations. `member()` is available
  for an existing custom membership table; a new built-in Groups app uses
  the parent-row example above.
- **public: true** lets anyone read every file in the collection at its public
  URL. It never grants upload, replace or delete, cannot be combined with
  `client.read`, and cannot be used on a member collection.
- **limits**: `maxSize` (`'25MB'` or bytes, at most your plan's per-file
  limit) and `types` (`'image/png'`, `'image/*'`).
- **path** is the collection's folder. Every upload is stored at
  `<path>/<file id>/<name>`. Collections cannot share or nest folders; up to
  20 collections.
- The membership table must not allow browser writes: change membership in a
  server function.

A declaration the platform cannot enforce refuses the deploy with
`SCHEMA_DECLARATION_INVALID` and one line per problem; nothing is applied.
Each deploy reports every collection and how many existing files sit in its
folder outside it.

## Use from the browser

```ts
import { files, type FileResult, type UploadedFile } from 'somewhere:files';

type Progress = (progress: { loaded: number; total: number }) => void;

// Upload, then return the file and its same-origin URL (authorized by the session on every request).
export async function uploadFile(file: File, onProgress?: Progress): Promise<FileResult<{ file: UploadedFile; url: string }>> {
  const result = await files.uploads.upload(file, { onProgress });
  if (result.error) return { data: null, error: result.error };   // { code, message, status }; nothing throws
  return { data: { file: result.data, url: files.uploads.url(result.data.id) }, error: null };
}

// One page: { items, next, has_more }; pass next back as cursor for more.
export function listUploads(cursor?: string | null) {
  return files.uploads.list({ limit: 20, cursor });
}

export function replaceUpload(id: string, file: Blob, onProgress?: Progress) {
  return files.uploads.replace(id, file, { onProgress });
}

export function deleteUpload(id: string) {
  return files.uploads.delete(id);
}

// A time-limited link: { url, expires_at, expires_in }.
export function shareUpload(id: string, expiresIn = 600) {
  return files.uploads.shareLink(id, { expiresIn });
}

// Member collection: the group key is named by the declaration (team_id).
export function uploadAttachment(teamId: string, file: File) {
  return files.attachments.upload(file, { team_id: teamId, name: file.name });
}

// Omit teamId to list every group you belong to.
export function listAttachments(teamId?: string) {
  return files.attachments.list({ team_id: teamId });
}

// Public collection: the upload result's url is the public URL.
export async function uploadAvatar(file: File): Promise<FileResult<string>> {
  const result = await files.avatars.upload(file);
  if (result.error) return { data: null, error: result.error };
  return { data: result.data.url, error: null };
}

export function avatarUrl(id: string, name: string): string {
  return files.avatars.publicUrl(id, name);
}

// serverOnly + public: a path inside the collection's folder.
export function assetUrl(path: string): string {
  return files.assets.publicUrl(path);
}
```

Every call returns `{ data, error }`. The client picks a single request or a
multipart upload by size, and checks `limits` before sending anything; the
platform enforces them regardless. A file's metadata is `{ id, name, size,
content_type, version, created_at, updated_at, mine }`, plus the group key in
member collections. It never carries another user's id or a storage path.

The client talks to your app's own origin (`/__sw/files`), so it works only
in pages served by the app. The files endpoint is served with your app's server
functions: an app with no function under `api/` and no declared browser data
answers `FILES_CLIENT_UNAVAILABLE` until it has one. A downloaded file that
is not an image, video, audio or PDF is delivered as a download, never
rendered inside your app.

## Answers

| Status | Code | Meaning |
|---|---|---|
| 401 | `AUTH_REQUIRED` | No signed-in user. Visitors (not signed in) cannot upload. |
| 403 | `FILE_ACCESS_DENIED` | The collection does not declare this operation. |
| 403 | `MEMBERSHIP_REQUIRED` | Uploading into a group you are not a member of. |
| 404 | `FILE_NOT_FOUND` | Missing, someone else's, another team's, or another collection's file — deliberately indistinguishable. |
| 409 | `FILES_CONTRACT_MISMATCH` | The declaration changed since the page loaded; reload. |
| 413 / 415 | `PAYLOAD_TOO_LARGE` / `FILE_TYPE_NOT_ALLOWED` | Outside `limits`. |

## Share links

- Default 10 minutes, at most 24 hours; a longer request is shortened, never
  refused, and `expires_at` shows the real time.
- A link stops working when the file is replaced or deleted (410
  `SIGNED_URL_STALE`), and when the person who made it can no longer read the
  file — removed from the team, for example (410 `SIGNED_URL_REVOKED`).
- Anyone holding a link can download until then. There is no per-link
  revocation; keep links short.
- Removing someone from a team takes effect on their very next request. Under
  `anyOf(owner(), member(...))` that includes the files they uploaded
  themselves, as with table rows; file access is checked on each request,
  before the file is served, rather than inside one database statement.

## In your functions

- Default `sw.fs` acts as the signed-in user with the collection's own rule:
  ownership grants access only where the scope includes `owner()` or
  `shared()` (under `anyOf(owner(), …)`, only while the uploader is in the
  file's group); a member may perform the
  operations the collection grants members on files of their groups, and a
  pure `member()` collection gives the uploader nothing beyond membership.
- A folder path is not membership. A signed-in `sw.fs` write, upload URL,
  copy or move that would put a new file inside a collection's folder answers
  409 `FILE_COLLECTION_PATH`, naming the way in: `files.<collection>.upload(...)`,
  or a `sw.fs.server` write adopted with `sw.fs.server.setOwner`.
- A collection file stays in its collection. A signed-in copy or move of it
  works inside the collection's folder (a copy is a new file of the
  collection, in the same group, allowed when that user may upload there) and
  answers 409 `FILE_COLLECTION_TRANSFER` anywhere else.
- `sw.fs.server` has project authority over every file; each operation is
  logged with authority `server`. You and your developer tools (CLI, MCP,
  dashboard) keep full access.
- Whether a collection file is public comes from the declaration:
  `make_public`, make-private and `visibility: 'public'` writes on it answer
  `FILE_VISIBILITY_DECLARED`.

## Files you already have

What a signed-in user's `sw.fs` may do with a file comes from that file's
own record and the current declaration, never from when the app or the file
was created:

- A collection file follows its collection's current rules.
- A file outside every collection is readable when it is public, and readable
  and changeable by the app user recorded as its owner.
- Any other private file belongs to the project. Only `sw.fs.server`, after
  your function's own check, and your developer tools reach it.

A signed-in user's `sw.fs` never creates a new file outside a collection
(403 `FILE_ACCESS_DENIED`) or inside a collection's folder (409
`FILE_COLLECTION_PATH`), so an upload endpoint that writes new files as the
signed-in user is refused. Declaring a collection changes nothing about
existing files, including files already inside its folder. A file joins a
collection only by being uploaded through `somewhere:files`, or by explicit
adoption.

A user's upload is stored privately in one of two ways:

- **Collection upload (the default).** Declare a collection and upload from
  the browser with `files.<collection>.upload(...)`. The platform checks the
  collection's rules on every request; no function is needed.
- **A privileged server function.** Verify the actor with
  `sw.auth.requireUser(req)`, check explicitly that this user may store or
  read this file, then call `sw.fs.server` with a path your code builds and
  confines to that user, such as `/uploads/${user.id}/${crypto.randomUUID()}`.
  Never pass a path the caller chose. Serve the file back the same way, or
  with a short `sw.fs.server.signedUrl` after the same check.

To move an app with a hand-written upload endpoint across, at its own pace:

1. Declare the collection (its folder may be the one the old endpoint uses).
2. Switch new browser uploads to `files.<collection>.upload(...)`. Old files
   stay readable under the rules above; serve project-owned ones from a
   function with `sw.fs.server` after your own check.
3. Adopt old files whenever convenient, from a function or `run_code`:
   `await sw.fs.server.setOwner(path, userId, { collection: 'uploads' })`
   (add `group` for a member collection). The file keeps its path and takes
   the collection's visibility. Refused outside the collection's folder and
   from a user's request. Safe to repeat.
4. Delete the old endpoint when it serves nothing. Skipping step 3 is fine.

### Automatic display images

Images shown in a page (including CSS backgrounds and script-created images) are delivered as
WebP at the same dimensions when the browser accepts WebP and the bytes identify a static JPEG
or non-animated PNG. Conversion is lossy, at quality 82, including PNG; pixels can change.
The WebP encoder removes embedded metadata, including EXIF location; the public original can still contain it.
A damaged image that still decodes may be shown as the encoder decodes it; downloads always return the uploaded bytes.
Downloads and script fetches get the original. `?original=1` always requests original bytes,
including with `w`; saving the displayed image (Save image as) may save the display copy.
Animated images, SVG and unrecognized inputs stay original. Explicit widths below remain for right-sizing.

A CDN or proxy placed in front of a custom domain must honour `Vary: Accept, Sec-Fetch-Dest`,
forward these headers, preserve queries and revalidate, or not cache these responses.
Customer service-worker/offline copies must revalidate mutable storage; retained offline bytes
are outside negotiation and revocation guarantees. Previously fresh browser entries may remain until expiry.

Cost: one more parameter combination per image revision per calendar month as the provider bills it;
the encoding work itself can repeat at another location or after eviction.
Worker execution and storage reads can repeat too.

### Responsive public images

Public uploaded PNG, JPEG, WebP and AVIF files accept exactly `?w=192`, `384`,
`768` or `1536`, returning WebP with the aspect ratio preserved and no enlargement.
Other widths, duplicate `w`, extra query parameters, Range requests and files
without a content revision use the original. SVG and other types stay original.
Each width of an image is encoded when first requested at a location and then served from that location's cache; it may be encoded again at another location or after eviction. Cloudflare bills a unique image-and-width once per calendar month.

All public storage responses revalidate access on each use, including originals and transform fallbacks.
A failed transform serves the guarded original.
`url(id)` remains the authorized file door; `publicUrl` only addresses public files.
For public server-only collections, use `publicUrl(path, width)`.

```tsx
// src/Avatar.tsx
import { files } from 'somewhere:files';

export function Avatar({ id, name }: { id: string; name: string }) {
  return <img
    src={files.avatars.publicUrl(id, name, 768)}
    srcSet={([192, 384, 768, 1536] as const).map(w =>
      `${files.avatars.publicUrl(id, name, w)} ${w}w`
    ).join(', ')}
    sizes="(max-width: 768px) 100vw, 768px"
    alt="Profile photo"
  />;
}
```

Choose `sizes` for your layout and dimensions from the actual image aspect ratio.
Use lazy loading for below-fold images, leaving the primary visible image eager.

Read, write, delete, and manage files in the project's storage.
Call these methods directly in your function; there's no URL to build and
no key to pass. Files are PRIVATE by default — pass
`visibility: 'public'` on the write (or call the make-public action)
to serve a file at its public `/storage` URL.

App users reach a file only where a rule gives it to them. `sw.fs` acts as
the signed-in user of the request (with no valid signed-in user it throws
`AUTH_REQUIRED`, 401, before any file is touched), and that user may:

- use the files of a declared file collection, as its rules allow;
- read a public file;
- read and change a file they already own.

Nothing else. A signed-in `sw.fs` call cannot create a file outside a
collection, and cannot read or change the project's files (files you or your
functions wrote with `sw.fs.server` or your developer key): writes answer
403 `FILE_ACCESS_DENIED`, reads 404 `NOT_FOUND`. The answer is the same
whether or not something exists at the path.

Files a function keeps for a user, like the examples below, use
`sw.fs.server` after the function's own check, with the path confined to
that user (`/uploads/${user.id}/…`). Never pass a path the caller chose.
Work that runs without a user, such as a cron or a queue message, uses
`sw.fs.server` the same way. A public file's URL stays public to everyone.

Browser uploads with per-user or per-team rules need no function: declare a
file collection in `db/schema.ts` and use `somewhere:files`
(`docs({ topic: 'declared-files' })`). `sw.fs.server.setOwner(path, userId,
{ collection })` adopts an existing file into a collection.

There are two file surfaces: deployed source is read with
`project_files_list` / `project_file_read`; `sw.fs` is runtime
storage for uploads and generated files. If you want `src/App.tsx`
or `api/foo.ts`, use `project_file_read`, not `sw.fs.read`.

## What you get out of the box (the industry-standard checklist)

- **File-level ACL (visibility).** Every file row carries a
  `visibility` flag (`public` | `private`); the platform checks
  it before bytes go out the door. Bucket-level ACLs alone can't
  give you private-by-row.
- **Object versioning + content-addressed writes.** Every write
  generates a new immutable object with a content-hash suffix and
  swaps the metadata pointer atomically. A half-written file never
  becomes visible.
- **Safe delete.** A delete removes the file's record first and its
  stored bytes afterwards, so a deleted file is never left listed without
  its bytes. If a read finds a file's bytes missing, it answers
  `NOT_FOUND` and removes the record; a developer can check a whole
  project with `file-tools` → `integrity-check-orphan-file-records`.
- **Versions + retention** by tier (3 / 10 / 50 / unlimited prior
  versions kept).
- **Signed URLs with TTL** via `sw.fs.signedUrl(path, { expiresIn })`.
- **SSRF protection on every platform-side fetch** (render, scrape,
  webhooks, AI ingest) — private and metadata IPs blocked before
  the request leaves.
- **Project-wide search, glob and diff** for developers and agents:
  `file-tools`.

Full reviewer-facing depth: <https://somewhere.cloud/docs/llms.txt>.

## sw.fs.write(path, content, options?)
```ts
// api/avatar.ts — store the signed-in user's avatar from the request body
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST') return new Response('Use POST.', { status: 405, headers: { Allow: 'POST' } });
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  const result = await sw.fs.server.write(`/uploads/${user.id}/avatar.png`, await req.arrayBuffer(), {
    content_type: 'image/png'
  })
  // result = { ok: true, data: { path, size_bytes: 12400, content_type: 'image/png',
  //            version: 1, content_revision } }
  // Read fields off result.data — e.g. result.data.path, result.data.size_bytes
  // (size_bytes, NOT size). result.path is undefined.
  return Response.json({ path: result.data.path, size_bytes: result.data.size_bytes })
}
```

## sw.fs.read(path, options?)
```ts
// api/avatar/get.ts — return the signed-in user's avatar
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  try {
    const file = await sw.fs.server.read(`/uploads/${user.id}/avatar.png`)
    // Success: Response object — file.arrayBuffer() / file.text() / file.json()
    return new Response(file.body, { headers: { 'Content-Type': file.headers.get('Content-Type') || 'application/octet-stream' } })
  } catch (err) {
    // Failure: throws an error with code, status, and message. Missing files throw
    // NOT_FOUND (404); an error response body is never returned as file content.
    if ((err as { status?: number }).status === 404) return new Response('Not found', { status: 404 })
    throw err
  }
}
```

The thrown error also applies to line-range reads. Apps deployed before this
behavior shipped need a new deploy to receive it. Reading a directory path,
such as `/uploads/<user id>/`, returns its listing as a JSON response;
`sw.fs.list` (below) returns a typed listing.

Read a line range from a stored text file (returns parsed JSON):

```ts
// api/imports/excerpt.ts — lines 50–75 of the signed-in user's import log
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  const slice = await sw.fs.server.read(`/logs/${user.id}/import-run.txt`, { lines: [50, 75] })
  // slice = { path, content: '...', lines: [50, 75], total_lines: 420,
  //           content_type, version, content_revision }
  return Response.json({ content: slice.content, total_lines: slice.total_lines })
}
```

## sw.fs.list(path, options?)
```ts
// api/uploads/index.ts — every file under the signed-in user's folder
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  // Directory listing. Pass { recursive: true } for the full subtree,
  // or { recursive: true, depth: 2 } to cap the walk.
  const all = await sw.fs.server.list(`/uploads/${user.id}/`, { recursive: true })
  // all = { path, type: 'directory', recursive: true, depth: null, entries: [{ path, name,
  //         type, size_bytes, content_type, version, updated_at }, ...] }
  // A listing without recursive also carries next_cursor.
  return Response.json(all.entries.map((entry) => entry.path))
}
```

## sw.fs.server — explicit project-wide file access

In a deployed handler, use `sw.fs.server.read/write/list` and the other
ordinary file operations when the application intentionally needs project-wide
access. Authorize the caller in your application before choosing this view;
it does not apply the request user's ownership filter. It uses the same
signatures and result shapes as `sw.fs` and does not expose the cross-file
scanners in `file-tools`. It is also the file view for crons, queue
messages and other work without a signed-in user, where plain `sw.fs` throws
`AUTH_REQUIRED`.

## sw.fs.dev — project-wide file view (run_code only)
`sw.fs.dev` and its search, glob and diff are described in `file-tools` →
`who-can-use-them`. Ordinary `sw.fs` calls need a
signed-in user; without one (a cron, for example) they throw `AUTH_REQUIRED`,
so use `sw.fs.server` there. A job started by a signed-in user reads and
writes files as that user. A row-bound job's grant (`sw.jobs` →
`act-on-one-row-for-the-signed-in-user`) gives its user no file access: plain
`sw.fs` is refused there. `sw.fs.server` stays your server code's explicit
project authority, so use it only after your own check.

## sw.fs.delete(path)
```ts
// api/uploads/remove.ts — delete one of the signed-in user's files
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST') return new Response('Use POST.', { status: 405, headers: { Allow: 'POST' } });
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  const result = await sw.fs.server.delete(`/uploads/${user.id}/old-file.txt`)
  // Directory deletes are recursive. delete does not throw on a refused
  // request: it resolves with the error body, so check ok.
  if (!result.ok) return Response.json({ error: result.error, message: result.message }, { status: 400 })
  return Response.json({ deleted: result.data.deleted })
}
```

## sw.fs.move(from, to, opts?)
```ts
// api/avatar/commit.ts — make a finished upload the signed-in user's avatar
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST') return new Response('Use POST.', { status: 405, headers: { Allow: 'POST' } });
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  // Move a finished upload without sending the bytes through your function.
  // overwrite replaces an existing destination in the same operation.
  // Avoid a separate delete-then-move: another request can race between them.
  const moved = await sw.fs.server.move(
    `/uploads/${user.id}/avatar.upload`,
    `/uploads/${user.id}/avatar.jpg`,
    { overwrite: true }
  )
  // moved = { from, to }. Without overwrite, a destination collision returns
  // VALIDATION_ERROR ("Destination ... already exists").
  return Response.json(moved)
}
```

