```ts
// api/notes/restore.ts — body { version }, a number from sw.fs.versions
export default async function(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST') return new Response('Use POST.', { status: 405, headers: { Allow: 'POST' } });
  const user = await sw.auth.fromRequest(req)
  if (!user) return Response.json({ error: 'sign in' }, { status: 401 })
  const input: unknown = await req.json().catch(() => null)
  const { version } = (input ?? {}) as { version?: unknown }
  if (typeof version !== 'number' || !Number.isInteger(version)) return Response.json({ error: 'version' }, { status: 400 })
  // Restores a previous version as the latest. Original versions stay in history.
  const restored = await sw.fs.server.restore(`/notes/${user.id}/draft.md`, version)
  // restored = { path, restored_version: 5, current_version: 8, content_revision }
  return Response.json(restored)
}
