## 4. Google, GitHub or Discord

The platform provides these sign-in clients. They work without app-specific
OAuth credentials or a Google Cloud project.

```tsx
// src/ui/GoogleButton.tsx — place it beside the form in src/ui/AuthCard.tsx
import { useState } from 'react';
import { auth, authErrorMessage } from '../services/auth';

export function GoogleButton() {
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  async function start() {
    setPending(true);
    setError(null);
    try {
      const url = await auth.googleSignInUrl({ redirectUri: `${window.location.origin}/auth/callback` });
      window.location.assign(url);
    } catch (reason: unknown) {
      setError(authErrorMessage(reason));
      setPending(false);
    }
  }
  return (
    <>
      <button type="button" className="button button--quiet" onClick={() => void start()} disabled={pending}>
        {pending ? 'Opening Google…' : 'Continue with Google'}
      </button>
      {error ? <p className="error" role="alert">{error}</p> : null}
    </>
  );
}
```

```tsx
// src/pages/AuthCallbackPage.tsx — the page at /auth/callback
import { useState } from 'react';
import { AuthCallback } from '@somewhere-cloud/sdk/react';

export function AuthCallbackPage() {
  const [failed, setFailed] = useState(false);
  return (
    <main className="loading">
      {/* Shows "Signing you in…", then the error; on success it opens / */}
      <p role={failed ? 'alert' : 'status'}><AuthCallback provider="google" onError={() => setFailed(true)} /></p>
      {failed ? <a href="/">Back to sign-in</a> : null}
    </main>
  );
}
```

The person isn't signed in yet when they land on `/auth/callback` or
`/auth/magic`, so these pages go in front of the starter's sign-in gate, not
inside the signed-in routes. This is the starter's `src/App.tsx` with both
pages added in front of the gate; `MagicLinkPage` is in step 5:

```tsx
// src/App.tsx
import type { User } from '../types/auth';
import { useAuthState } from './auth/hooks';
import { APP_NAME } from './config';
import { AuthCallbackPage } from './pages/AuthCallbackPage';
import { HomePage } from './pages/HomePage';
import { MagicLinkPage } from './pages/MagicLinkPage';
import { NotFoundPage } from './pages/NotFoundPage';
import { SignInPage } from './pages/SignInPage';
import { linkTo, ROUTES, usePathname } from './routes';
import { AppShell } from './ui/AppShell';
import { SessionUnavailable } from './ui/feedback';

export function App() {
  const pathname = usePathname();
  const session = useAuthState();

  // Sign-in returns run before the gate: the session doesn't exist until they finish.
  if (pathname === '/auth/callback') return <AuthCallbackPage />;
  if (pathname === '/auth/magic') return <MagicLinkPage />;

  // Before the server has answered, the app's frame shows at once, with no
  // account and no full-page loading screen; the page fills in on the answer.
  if (session.status === 'loading' || session.status === 'signing-out') {
    return (
      <AppShell appName={APP_NAME} homeLink={linkTo(ROUTES.home)} busy>
        {session.status === 'signing-out' ? <p role="status">Signing out…</p> : null}
      </AppShell>
    );
  }
  if (session.status === 'signed-out') return <SignInPage />;
  if (session.status === 'unavailable') {
    return <SessionUnavailable keepsWork={false} checkStatus={session.checkStatus} retrying={session.retrying} onRetry={session.retry} />;
  }
  const suspended = session.status === 'suspended';
  return (
    <>
      {suspended ? <SessionUnavailable keepsWork checkStatus={session.checkStatus} retrying={session.retrying} onRetry={session.retry} /> : null}
      <div hidden={suspended} inert={suspended}>
        <PrivateRoutes key={session.user.id} user={session.user} />
      </div>
    </>
  );
}

function PrivateRoutes({ user }: { user: User }) {
  const pathname = usePathname();
  switch (pathname) {
    case ROUTES.home:
      return <HomePage user={user} />;
    default:
      return <NotFoundPage user={user} />;
  }
}
```

The provider returns with a one-time `?code=`; `AuthCallback` exchanges it for
the cookie session and opens `/`, so no session token ever appears in a URL. GitHub and Discord are the same
with `githubSignInUrl` / `discordSignInUrl` and `provider="github"` or
`"discord"`. The redirect must be on your project's address or a domain
attached to it: `sw.auth` → `social-oauth`.

## 5. Sign-in links

```ts
// src/services/sign-in-link.ts — call from a form on the sign-in page
import { auth } from './auth';

export function sendSignInLink(email: string): Promise<void> {
  return auth.sendMagicLink({ email });
}
```

```tsx
// src/pages/MagicLinkPage.tsx — /auth/magic, the page the emailed link opens
import { useEffect, useRef, useState } from 'react';
import { auth, authErrorMessage } from '../services/auth';

export function MagicLinkPage() {
  const [error, setError] = useState<string | null>(null);
  const started = useRef(false);
  useEffect(() => {
    if (started.current) return; // the token works once; never verify it twice
    started.current = true;
    const token = new URLSearchParams(window.location.search).get('token');
    if (!token) {
      setError('This sign-in link is incomplete. Request a new one.');
      return;
    }
    auth.verifyMagicLink({ token })
      .then(() => window.location.replace('/'))
      .catch((reason: unknown) => setError(authErrorMessage(reason)));
  }, []);
  return (
    <main className="loading">
      <p role={error ? 'alert' : 'status'}>{error ?? 'Signing you in…'}</p>
      {error ? <a href="/">Back to sign-in</a> : null}
    </main>
  );
}
```

The email links to `/auth/magic?token=…` on your app, which `src/App.tsx`
above sends to this page.
The link works once; a completed sign-in uses the same cookie session. Details and expiry: `sw.auth` →
`magic-links-passwordless-sign-in`.

Sign-in links, verification codes and invitations come from the platform's
auth sender and reach any address. Your own `sw.email.send` mail reaches only
this project's users and its owner unless you add a sender domain, so invite
new people with `sw.auth.invite` (`sw.auth` → `invitations`). Verifying
the address of a password account: `sw.auth` → `with-a-cookie-session`.

## 6. A second factor

Email sign-in codes: the app owner sets the policy (`PUT /v1/auth/mfa/policy`,
`optional` or `required`), and then a password sign-in answers
`{ mfa_required: true, mfa_token }` with no session until the user enters the code
from their email (`sw.auth.mfa.challengeWithCookie({ mfa_token, code })`). The
full contract, turning codes off and the 72-hour recovery: `sw.auth` →
`email-sign-in-codes`. Authenticator-app codes are not available.

## 7. Sign out

The starter's sign-out button already calls `auth.signOut()`. Private pages
close as soon as sign-out starts. Two answers are shown, never hidden:

- **Sign-out not confirmed.** The server failed to confirm revocation, so the
  session may still be active. The starter shows "We couldn't confirm sign-out with
  the server" with **Sign out again**.
- **Session can't be checked.** A sign-in check failed without an answer. The
  starter shows "We can't confirm your sign-in" with **Try again**. Until the
  server answers, the user is neither signed in nor signed out; a user it had
  already confirmed keeps their unsaved work.

To sign out from another place, use `useSignOut()` from `src/auth/hooks.ts`
(`sw.auth` → `logout`).

## 7. Team invites

A team app on built-in groups: someone creates a team and becomes its owner,
invites people by email, and the members share the team's tasks. The platform
keeps the team, its members, their roles and the invitations; you declare
which rows belong to a team and add your own rules about rows.

### Team tables

```ts
// db/schema.ts
import { boolean, group, id, schema, table, text } from 'somewhere/db';

export default schema({
  tasks: table(
    {
      id: id(),
      team_id: text(),
      title: text(),
      done: boolean({ default: false }),
      created_by: text(),
    },
    {
      scope: group({ column: 'team_id' }),
      // Members read and edit from the browser; api/tasks.ts creates and deletes.
      client: { read: ['id', 'team_id', 'title', 'done', 'created_by'], create: null, update: ['title', 'done'], delete: false },
    },
  ),
});
```

There is no teams table and no membership table: a team is a built-in group,
and `team_id` holds its id.

### Create a team

```ts
// api/teams.ts — POST { name } creates a team owned by the caller; GET lists the caller's teams
export default async function teams(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST' && req.method !== 'GET') {
    return new Response(null, { status: 405, headers: { Allow: 'GET, POST' } });
  }
  if (!(await sw.auth.fromRequest(req))) return Response.json({ error: 'Sign in first.' }, { status: 401 });
  if (req.method === 'GET') {
    // Also finishes any accepted invitation not yet confirmed, and reports it.
    const listed = await sw.groups.list(req);
    if (listed.error) return Response.json({ error: listed.error.message }, { status: listed.error.status });
    return Response.json({ teams: listed.data.items, invitations: listed.data.invitations });
  }
  const body = (await req.json().catch(() => null)) as { name?: unknown } | null;
  const name = typeof body?.name === 'string' ? body.name.trim() : '';
  if (!name) return Response.json({ error: 'Name the team.' }, { status: 400 });
  const created = await sw.groups.create(req, { name });
  if (created.error) return Response.json({ error: created.error.message }, { status: created.error.status });
  return Response.json({ team_id: created.data.id }, { status: 201 });
}
```

### Invite, then join

```ts
// api/invites.ts — POST { team_id, email }: an owner or admin invites a member
export default async function invite(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST') return new Response(null, { status: 405, headers: { Allow: 'POST' } });
  if (!(await sw.auth.fromRequest(req))) return Response.json({ error: 'Sign in first.' }, { status: 401 });
  const body = (await req.json().catch(() => null)) as { team_id?: unknown; email?: unknown } | null;
  if (typeof body?.team_id !== 'string' || typeof body.email !== 'string') {
    return Response.json({ error: 'Send team_id and email.' }, { status: 400 });
  }
  const invited = await sw.groups.invite(req, body.team_id, { email: body.email, role: 'member', redirect_uri: '/join' });
  // ROLE_NOT_GRANTABLE: the caller's role can't invite members; no email was sent.
  if (invited.error) return Response.json({ error: invited.error.message, code: invited.error.code }, { status: invited.error.status });
  return Response.json({ id: invited.data.invite.id, delivery: invited.data.delivery });
}
```

The email links to your app's `/auth/magic` page. Following it signs the
invitee in as the invited address and opens `/join?invite_id=<id>`. The sign-in
result reports the membership in `group_invitation`: `completed` means they are
a member with the invited role; `pending` means it is not confirmed yet;
`refused` carries a `code`, for example `INVITATION_REVOKED` or
`INVITATION_AUTHORITY_LOST` when the inviter can no longer grant the role. Your
`/join` page loads `GET /api/teams`: listing the user's teams also completes
pending invitations, a few at a time, and reports each one in `invitations`.
Your app never adds the member itself.

The emailed link is a one-time sign-in for the invited address. Whoever opens
it is signed in as that address, and that address becomes the member, so treat
the link like a password: it must not be forwarded. The membership always
belongs to the invited address, never to another account the person opening it
was already signed in as. An invitation expires at its `expires_at`
(`expires_in` sets how long it lasts). To withdraw one earlier, call
`sw.groups.revokeInvitation(req, inviteId)` from a function, with the `id`
that `api/invites.ts` returned; the group's own rules decide who may.
Re-inviting is how a removed member comes back.

### Who created a task comes from the session

`created_by` is an ordinary column. If the browser could write it, any
member could create a task in someone else's name, so tasks are created and
deleted here. To let the creator or a team owner delete, declare it instead
of writing it: `sw.db` → `owner-or-member-and-parent-access` ("creator or
team owner can delete") does it with `anyOf(owner(), group(...))` and built-in
groups. For a roster your app manages without email verification, see
`somewhere docs declared-data --section teams-without-email-verification`.

```ts
// api/tasks.ts — POST { team_id, title } adds a task; DELETE { id } removes your own
export default async function tasks(req: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  if (req.method !== 'POST' && req.method !== 'DELETE') {
    return new Response(null, { status: 405, headers: { Allow: 'POST, DELETE' } });
  }
  const user = await sw.auth.requireUser(req);
  const body = (await req.json().catch(() => null)) as { id?: unknown; team_id?: unknown; title?: unknown } | null;
  if (req.method === 'DELETE') {
    if (typeof body?.id !== 'string' || body.id === '') {
      return Response.json({ error: 'Send the task id.' }, { status: 400 });
    }
    // group() limits this to the caller's teams; "only the creator" is this app's rule.
    const { changes } = await sw.db.remove('tasks', { where: { id: body.id, created_by: user.id } });
    return changes === 1 ? Response.json({ deleted: true }) : Response.json({ error: 'Only its creator can delete a task.' }, { status: 404 });
  }
  if (typeof body?.team_id !== 'string' || typeof body.title !== 'string') {
    return Response.json({ error: 'Send team_id and title.' }, { status: 400 });
  }
  // group() checks the caller belongs to team_id: 403 POLICY_AUTHORITY_REQUIRED otherwise.
  const { data: [task] } = await sw.db.insert('tasks', { team_id: body.team_id, title: body.title, created_by: user.id });
  return Response.json({ task });
}
```

The body cannot choose the creator: the function never reads one. The
browser keeps the generated client for `data.tasks.list`, `get` and
`update`.

### Which rule lives where

- **The platform:** who belongs to a team and with which role, who may invite
  or change roles, and who may read or change a task (current members of its
  team), on every path: the generated client, `/__sw/data`,
  `sw.db.from`/`insert`/`update`/`remove` and `sw.db.tx`.
- **Your functions:** rules about rows (only the creator deletes). A rule about
  another person's membership, such as "the payer must be in the team", is a
  read with `sw.groups.members` in your function before the write.
- **Work with no user** (a webhook, a cron): `sw.db.server.*`, after your
  function has authorized it.

### Check the team flow

- Invite `bob@<project>.test.somewhere.site`, then
  `somewhere email test-inbox bob@<project>.test.somewhere.site` prints the
  one invite email and its link.
- Open the link in a browser: Bob is signed in, lands on `/join`, and
  `GET /api/teams` lists the team.
- As a non-member, call `/__sw/data` directly for `tasks`: `list` → `[]`,
  `get` → `null`, `update` → 404 (`declared-data` →
  `calling-the-data-endpoint-directly`).
- The same check works in a preview with preview users: the invite is captured
  (`somewhere preview mail`), and Bob signs up with the invited address and
  verifies it instead of opening a sign-in link.

An app that already keeps its own membership table with `member()` keeps
working; moving it to built-in groups is an explicit mapping
(`sw.groups` → `apps-with-their-own-membership-table`).

Users upload, list, open and delete their own files from the page. Declare a
file collection; the generated `somewhere:files` client sends each file
straight from the browser to storage, and the platform checks your rules on
every request. You write no upload endpoint.

## 1. Declare the collection

```ts
// db/schema.ts
import { files, owner, schema } from 'somewhere/db';

export default schema({}, {
  files: {
    uploads: files({
      path: '/uploads',
      scope: owner(),
      client: { read: true, upload: true, delete: true },
      limits: { maxSize: '20MB', types: ['image/*', 'application/pdf', 'text/plain'] },
    }),
  },
});
```

`owner()` gives each signed-in user their own files. `'20MB'` and the type
list are this example's choices; the client checks them before sending and the
platform enforces them. Your plan's per-file ceiling is in `limits`. If the
schema already declares tables, keep them in the first argument.

## 2. Upload, list and delete from the page

```tsx
// src/ui/Uploads.tsx — the signed-in user's own files
import { useEffect, useState, type ChangeEvent } from 'react';
import { files, type FileMeta } from 'somewhere:files';

type Listing = { status: 'loading' } | { status: 'error'; message: string } | { status: 'ready'; items: FileMeta[]; more: boolean };

export function Uploads() {
  const [listing, setListing] = useState<Listing>({ status: 'loading' });
  const [actionError, setActionError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  async function refresh() {
    // The first 50 files; has_more says whether there are more to page through.
    const { data, error } = await files.uploads.list({ limit: 50 });
    setListing(error ? { status: 'error', message: error.message } : { status: 'ready', items: data.items, more: data.has_more });
  }

  useEffect(() => { void refresh(); }, []);

  async function onPick(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;
    setBusy(true);
    setActionError(null);
    const { error } = await files.uploads.upload(file);
    setBusy(false);
    if (error) return setActionError(error.message);
    await refresh();
  }

  async function remove(id: string) {
    const { error } = await files.uploads.delete(id);
    if (error) return setActionError(error.message);
    await refresh();
  }

  return (
    <section className="panel">
      <label htmlFor="upload-file">Add a file</label>
      <input id="upload-file" type="file" onChange={(event) => void onPick(event)} disabled={busy} />
      {actionError ? <p className="error" role="alert">{actionError}</p> : null}
      {listing.status === 'loading' ? <p role="status">Loading your files…</p> : null}
      {listing.status === 'error' ? (
        <p className="error" role="alert">
          {listing.message} <button type="button" className="button button--quiet" onClick={() => void refresh()}>Try again</button>
        </p>
      ) : null}
      {listing.status === 'ready' && listing.items.length === 0 ? <p id="uploads-empty">No files yet.</p> : null}
      {listing.status === 'ready' && listing.items.length > 0 ? (
        <ul>
          {listing.items.map((item) => (
            <li key={item.id}>
              <a className="upload__name" href={files.uploads.url(item.id)}>{item.name}</a>
              <button type="button" className="button button--quiet" onClick={() => void remove(item.id)}>Delete</button>
            </li>
          ))}
        </ul>
      ) : null}
      {listing.status === 'ready' && listing.more ? <p className="hint">Showing your first 50 files.</p> : null}
    </section>
  );
}
```

Render `<Uploads />` on a signed-in page, such as the starter's
`src/pages/HomePage.tsx`. "No files yet." appears only after the list has
loaded successfully; while it loads or after a failed list, the page says so
instead. The list shows the first 50 files (`has_more` tells you there are
more; pass its `next` as `cursor` to page). Every call resolves to
`{ data, error }` and none throws for a refusal: a type outside `limits`, a file that is too large, a
signed-out caller or a lost connection (`NETWORK_ERROR`) arrives in `error`
with a `code`, `status` and `message`. `url(id)` is checked against the session
on every request, so a link only opens for its owner. Large files are sent in
parts by the same `upload` call; pass `onProgress` to show progress.

