## 6. Show progress automatically

The job's structured write lands in that user's `note_summaries`, so a live
view over their summaries refreshes automatically when it changes. No **Check
status** clicks and no polling loop. Declare the view in a function:

```ts
// api/recent-summaries.ts — the signed-in user's latest summaries, as a live view
export default async function recentSummaries(request: Request, sw: SomewhereRuntimeContext): Promise<Response> {
  const user = await sw.auth.fromRequest(request);
  if (!user) return Response.json({ error: 'Sign in.' }, { status: 401 });
  return Response.json(await sw.rooms.live('summaries.recent', sw.db.from('note_summaries', {
    columns: ['id', 'note_count', 'created_at'],
    order: [['created_at', 'desc'], ['id', 'desc']],
    limit: 5,
  })));
}
