## Start from a signed-in app

Ask before destructive or paid actions unless the user already authorized them.

Create an app with `somewhere init`, or ask your connected agent to create a
project with the sign-in starter. Keep the starter's auth and layout files.
Add the files below, replacing its `src/pages/HomePage.tsx`. Deploy raw source
with `somewhere deploy` or `project_deploy`; there is no frontend build step.

This recipe uses `provider: 'anthropic'` with an image-capable model from
`ai_catalog` and structured output. The example selects `claude-haiku-5-5`.
Other providers currently refuse image and PDF inputs. Check the account's AI
balance and the project's spend cap before inviting people to use it.

## What the app handles

1. **Private upload.** An `owner()` file collection accepts JPEG, PNG, GIF,
   WebP and PDF files up to the example's 5 MiB limit. The browser sends no
   owner id; the signed-in session determines who can reach each file.
2. **Read once.** The function requires the user, checks a per-user reading
   limit, then reads that user's upload and sends its bytes in one
   `sw.ai.chat` request. It omits `conversation_id`. One request can include
   a separately billed structured-output repair.
3. **Review.** The result is an unsaved form. The user can change the merchant,
   date, currency, total and line items. Invalid fields keep Save disabled.
4. **Save explicitly.** Save creates an owner-scoped row from the reviewed
   values. A unique owner-and-file key prevents a second receipt for that
   upload. A second click while an action is running is ignored.
5. **Recover an uncertain save.** A lost response shows **Check saved
   receipt**, which only reads. If the row is still absent, the user can
   choose **Save again**; the unique key prevents a duplicate. The app never
   repeats a model request or save automatically.

The example sets a per-user counter to 20 readings an hour before file or
model access. Warm instances can admit a few extra readings. The project's AI
spend cap is a separate control. A refused or failed reading leaves manual
entry available.

## Files

The schema, function, services and page below form one example. Keep their
paths so the relative imports resolve. `api/_lib` contains shared server code;
`api/receipts/extract.ts` is the request handler.

### Schema: private uploads and saved receipts

```ts
// db/schema.ts
import { files, id, json, number, owner, schema, table, text } from 'somewhere/db';

// receipts: each signed-in user sees and writes only their own saved receipts
// through the generated somewhere:data client. The browser creates a row only
// after the user reviews the extracted values and presses Save. One receipt
// per uploaded file per user: user_id is the owner column owner() manages, so
// a second save of the same file is refused (DATA_CONFLICT) instead of
// creating a duplicate, and one user's file ids reveal nothing to another.
//
// receipt_files: private uploads, readable only by the uploader. The types are
// exactly the image and PDF formats the model accepts; 5MB (5 MiB) keeps the
// base64-encoded request well inside the platform's attachment request limit.
export default schema({
  receipts: table(
    {
      id: id(),
      file_id: text(),
      merchant: text(),
      purchased_on: text({ default: '' }),
      currency: text({ default: '' }),
      total: number({ nullable: true }),
      lines: json(),
    },
    {
      scope: owner(),
      unique: [['user_id', 'file_id']],
      client: {
        read: ['id', 'file_id', 'merchant', 'purchased_on', 'currency', 'total', 'lines'],
        create: ['file_id', 'merchant', 'purchased_on', 'currency', 'total', 'lines'],
        delete: true,
        identity: 'authenticated',
      },
    },
  ),
}, {
  files: {
    receipt_files: files({
      path: '/receipts',
      scope: owner(),
      client: { read: true, upload: true, delete: true },
      limits: { maxSize: '5MB', types: ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'] },
    }),
  },
});
```

### Shared types

```ts
// types/receipts.ts
// Type aliases, not interfaces: a line list is stored in a json() column, and
// only a type alias is assignable to the generated client's JSON value type.
export type ReceiptLine = { description: string; amount: number };

/** What extraction proposes and the user edits. Nothing is saved until Save. */
export type ReceiptDraft = {
  file_id: string;
  merchant: string;
  /** YYYY-MM-DD, or '' when the receipt shows no date. */
  purchased_on: string;
  /** ISO 4217 code such as 'USD', or '' when the receipt shows none. */
  currency: string;
  lines: ReceiptLine[];
  total: number | null;
};

export type ReceiptDraftErrors = Partial<Record<'merchant' | 'purchased_on' | 'currency' | 'lines' | 'total', string>>;

/** The extraction function's answer. `retry` tells the page whether trying the
 *  same file again is reasonable; the page never retries on its own. */
export type ExtractAnswer =
  | { ok: true; draft: ReceiptDraft }
  | { ok: false; error: { code: string; message: string; retry: boolean } };

/** A save either committed, was refused (nothing written), or its outcome is
 *  unknown because the response was lost. Unknown is never reported as unsaved. */
export type SaveOutcome =
  | { kind: 'saved'; message: string }
  | { kind: 'refused'; message: string }
  | { kind: 'unknown'; message: string };

/** A read-only look for this file's saved receipt. */
export type SavedCheck = { kind: 'found'; message: string } | { kind: 'not-found' } | { kind: 'unknown'; message: string };

export type ReceiptFlowStep =
  | { kind: 'choose' }
  | { kind: 'uploading' }
  | { kind: 'extracting'; fileId: string }
  | { kind: 'review'; draft: ReceiptDraft }
  | { kind: 'saving'; draft: ReceiptDraft }
  /** The save's outcome is unknown. `checked`: a look found nothing yet. */
  | { kind: 'unconfirmed'; draft: ReceiptDraft; checked: boolean }
  | { kind: 'saved'; message: string };
```

### Server helpers: model, response schema and answer checks

```ts
// api/_lib/receipt-extraction.ts
import type { ExtractAnswer, ReceiptDraft, ReceiptLine } from '../../types/receipts';

// This Anthropic model accepts images, PDFs and response_schema.
export const RECEIPT_MODEL = 'claude-haiku-5-5';
/** This example's own per-user limit on metered readings (not a platform quota). */
export const RECEIPT_READS_PER_HOUR = 20;
/** db/schema.ts receipt_files maxSize: '5MB' is 5 MiB. */
export const RECEIPT_MAX_BYTES = 5 * 1024 * 1024;
const MAX_LINES = 100;
const MAX_TEXT = 200;

/** The structured answer the model must return; validated again below. */
export const RECEIPT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['merchant', 'purchased_on', 'currency', 'lines', 'total'],
  properties: {
    merchant: { type: 'string', description: 'Store or business name as printed.' },
    purchased_on: { type: 'string', description: 'Purchase date as YYYY-MM-DD, or an empty string if none is shown.' },
    currency: { type: 'string', description: 'ISO 4217 code such as USD, or an empty string if unclear.' },
    lines: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['description', 'amount'],
        properties: { description: { type: 'string' }, amount: { type: 'number' } },
      },
    },
    total: { type: ['number', 'null'], description: 'Total paid, or null if not shown.' },
  },
} as const;

export const RECEIPT_PROMPT = 'Read this receipt. Return each purchased item with its price, the merchant, '
  + 'the purchase date and the total. Copy values as printed; do not invent missing ones.';

/** A collection file id is one path segment; anything else is refused. */
export function isFileId(value: unknown): value is string {
  return typeof value === 'string' && value.length > 0 && value.length <= 128
    && !value.includes('/') && value !== '.' && value !== '..';
}

const IMAGE_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp'] as const;
type ImageType = (typeof IMAGE_TYPES)[number];

/** The native input block for an uploaded file, or null for any other type. */
export function inputBlock(contentType: string | null, bytes: Uint8Array): SomewhereAiImageInputBlock | SomewhereAiDocumentInputBlock | null {
  const data = toBase64(bytes);
  if (contentType === 'application/pdf') {
    return { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data } };
  }
  if (IMAGE_TYPES.includes(contentType as ImageType)) {
    return { type: 'image', source: { type: 'base64', media_type: contentType as ImageType, data } };
  }
  return null;
}

/** Plain base64 (no data: prefix), encoded in chunks to stay within argument limits. */
export function toBase64(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
}

function text(value: unknown, max = MAX_TEXT): string | null {
  return typeof value === 'string' ? value.trim().slice(0, max) : null;
}

function money(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) ? Math.round(value * 100) / 100 : null;
}

/** The model's structured answer as a draft, or null when it is not one. */
export function draftFromModel(parsed: unknown, fileId: string): ReceiptDraft | null {
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
  const answer = parsed as Record<string, unknown>;
  const merchant = text(answer.merchant);
  const purchasedOn = text(answer.purchased_on, 10);
  const currency = text(answer.currency, 3);
  if (merchant === null || purchasedOn === null || currency === null || !Array.isArray(answer.lines)) return null;
  const lines: ReceiptLine[] = [];
  for (const raw of answer.lines.slice(0, MAX_LINES)) {
    const line = raw && typeof raw === 'object' ? raw as Record<string, unknown> : {};
    const description = text(line.description);
    const amount = money(line.amount);
    if (description === null || amount === null) return null;
    lines.push({ description, amount });
  }
  const total = answer.total === null ? null : money(answer.total);
  if (total === null && answer.total !== null) return null;
  return {
    file_id: fileId,
    merchant,
    purchased_on: /^\d{4}-\d{2}-\d{2}$/.test(purchasedOn) ? purchasedOn : '',
    currency: /^[A-Za-z]{3}$/.test(currency) ? currency.toUpperCase() : '',
    lines,
    total,
  };
}

export function refusal(status: number, code: string, message: string, retry: boolean): Response {
  const body: ExtractAnswer = { ok: false, error: { code, message, retry } };
  return Response.json(body, { status });
}

/**
 * A failed model call, in words the page can show. Messages say what the
 * user can do next and make no claim about charges; only a rate limit is
 * offered as worth trying again later.
 */
export function modelFailure(reason: unknown): Response {
  const code = reason && typeof reason === 'object' && typeof (reason as { code?: unknown }).code === 'string'
    ? (reason as { code: string }).code : '';
  switch (code) {
    case 'INSUFFICIENT_BALANCE':
    case 'PAID_API_NOT_ACTIVATED':
    case 'PAID_AI_DISABLED':
      return refusal(402, code, 'Receipt reading is unavailable right now. Enter the values yourself.', false);
    case 'AI_SPEND_CAP_REACHED':
      return refusal(429, code, 'Receipt reading is paused for now. Enter the values yourself.', false);
    case 'AI_INPUT_UNSUPPORTED':
    case 'AI_INPUT_TOO_LARGE':
      return refusal(400, code, 'This file could not be read. Upload a JPEG, PNG, GIF, WebP or PDF under 5 MB.', false);
    case 'MODEL_CAPABILITY_UNSUPPORTED':
    case 'MODEL_RETIRED':
      return refusal(503, code, 'Receipt reading is unavailable with the configured model. Enter the values yourself.', false);
    case 'RATE_LIMITED':
      return refusal(429, code, 'Too many receipts at once. Try again in a minute.', true);
    default:
      return refusal(502, 'EXTRACTION_FAILED',
        'Reading the receipt did not finish. It was not retried automatically, because it may already have been charged. '
        + 'Enter the values yourself, or try again once.', false);
  }
}
