### The extraction function

```ts
// api/receipts/extract.ts
// POST /api/receipts/extract  { file_id }  →  { ok: true, draft } | { ok: false, error }
//
// Reads one of the signed-in user's own receipt uploads, makes one sw.ai.chat
// request for structured rows (the platform may add one separately billed
// structured-output repair inside it), and returns them as an unsaved draft.
// Saving happens later, in the browser, only after the user reviews the values.
import type { ExtractAnswer } from '../../types/receipts';
import {
  draftFromModel, inputBlock, isFileId, modelFailure, RECEIPT_MAX_BYTES, RECEIPT_MODEL,
  RECEIPT_PROMPT, RECEIPT_READS_PER_HOUR, RECEIPT_SCHEMA, refusal,
} from '../_lib/receipt-extraction';

export default async (req: Request, sw: SomewhereRuntimeContext): Promise<Response> => {
  if (req.method !== 'POST') return new Response('Method not allowed', { status: 405, headers: { Allow: 'POST' } });
  // Required first: sw.fs below acts as this verified user. Without a signed-in
  // user it would act with project authority over every file.
  const user = await sw.auth.requireUser(req);

  const body: unknown = await req.json().catch(() => null);
  const fileId = body && typeof body === 'object' ? (body as { file_id?: unknown }).file_id : undefined;
  if (!isFileId(fileId)) return refusal(400, 'VALIDATION_ERROR', 'Choose a receipt to read.', false);

  // Each reading is metered, so this example allows each user 20 per hour,
  // counted before any file read or model request.
  const limit = await sw.rateLimit.check(`receipt-extract:${user.id}`, RECEIPT_READS_PER_HOUR, 3600);
  if (!limit.allowed) {
    return refusal(429, 'RECEIPT_RATE_LIMITED', `You can read ${RECEIPT_READS_PER_HOUR} receipts an hour. Try again later, or enter the values yourself.`, false);
  }

  const file = await findOwnedReceipt(sw, fileId);
  if (!file) return refusal(404, 'RECEIPT_NOT_FOUND', 'That receipt was not found. Upload it again.', false);
  if (file.size_bytes > RECEIPT_MAX_BYTES) return refusal(413, 'RECEIPT_TOO_LARGE', 'Receipts must be under 5 MB.', false);

  const bytes = new Uint8Array(await (await sw.fs.read(file.path)).arrayBuffer());
  const block = inputBlock(file.content_type, bytes);
  if (!block) return refusal(415, 'RECEIPT_TYPE_UNSUPPORTED', 'Upload a JPEG, PNG, GIF, WebP or PDF.', false);

  let result: SomewhereAiChatResult;
  try {
    // No conversation_id: this is a one-shot extraction. A failed call is
    // never repeated here.
    result = await sw.ai.chat({
      provider: 'anthropic',
      model: RECEIPT_MODEL,
      max_tokens: 2048,
      response_schema: RECEIPT_SCHEMA,
      messages: [{ role: 'user', content: [block, { type: 'text', text: RECEIPT_PROMPT }] }],
      stream: false,
    });
  } catch (reason: unknown) {
    return modelFailure(reason);
  }

  const draft = draftFromModel(result.parsed, fileId);
  if (!draft) {
    return refusal(422, 'RECEIPT_UNREADABLE', 'No rows could be read from this receipt. Enter them yourself, or upload a clearer image.', false);
  }
  const answer: ExtractAnswer = { ok: true, draft };
  return Response.json(answer);
};

/** The one file stored under this upload's id, if the signed-in user owns it.
 *  Listing as that user shows only their own files, so another user's id
 *  answers exactly like a missing one. */
async function findOwnedReceipt(sw: SomewhereRuntimeContext, fileId: string): Promise<SomewhereFsListEntry | null> {
  let listing: SomewhereFsListResult;
  try {
    listing = await sw.fs.list(`/receipts/${fileId}/`);
  } catch (reason: unknown) {
    const status = reason && typeof reason === 'object' ? (reason as { status?: unknown }).status : undefined;
    if (status === 403 || status === 404) return null;
    throw reason;
  }
  const found = listing.entries.filter((entry) => entry.type === 'file');
  return found.length === 1 ? found[0] : null;
}
```

### Browser services: upload, read, save and check

```ts
// src/services/receipts.ts
import { data, DataError } from 'somewhere:data';
import { files } from 'somewhere:files';
import type { ExtractAnswer, ReceiptDraft, ReceiptDraftErrors, SavedCheck, SaveOutcome } from '../../types/receipts';

// Mirrors db/schema.ts receipt_files; the platform enforces the same limits.
export const RECEIPT_TYPES = ['image/jpeg', 'image/png', 'image/gif', 'image/webp', 'application/pdf'] as const;
export const RECEIPT_MAX_BYTES = 5 * 1024 * 1024;

export type Outcome<T> = { ok: true; value: T } | { ok: false; message: string; retry: boolean };

/** Checked here for a fast answer; the collection's limits are the authority. */
export function checkReceiptFile(file: File): string | null {
  if (!RECEIPT_TYPES.includes(file.type as (typeof RECEIPT_TYPES)[number])) return 'Choose a JPEG, PNG, GIF, WebP or PDF.';
  if (file.size > RECEIPT_MAX_BYTES) return 'Receipts must be under 5 MB.';
  return null;
}

/** Private upload into the signed-in user's receipt_files collection. */
export async function uploadReceipt(file: File): Promise<Outcome<string>> {
  const problem = checkReceiptFile(file);
  if (problem) return { ok: false, message: problem, retry: false };
  const result = await files.receipt_files.upload(file);
  if (result.error) {
    if (result.error.code === 'PAYLOAD_TOO_LARGE') return { ok: false, message: 'Receipts must be under 5 MB.', retry: false };
    if (result.error.code === 'FILE_TYPE_NOT_ALLOWED') return { ok: false, message: 'Choose a JPEG, PNG, GIF, WebP or PDF.', retry: false };
    if (result.error.code === 'AUTH_REQUIRED') return { ok: false, message: 'Your session ended. Sign in again.', retry: false };
    return { ok: false, message: result.error.message || 'The upload failed. Try again.', retry: true };
  }
  return { ok: true, value: result.data.id };
}

/** One extraction request. The caller decides whether to ask again. */
export async function extractReceipt(fileId: string): Promise<Outcome<ReceiptDraft>> {
  let response: Response;
  try {
    response = await fetch('/api/receipts/extract', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ file_id: fileId }),
    });
  } catch {
    // The request may or may not have reached the server, so this is not
    // presented as safe to repeat.
    return { ok: false, message: 'Could not confirm the receipt was read. Check your connection, then enter the values or try once more.', retry: false };
  }
  if (response.status === 401) return { ok: false, message: 'Your session ended. Sign in again.', retry: false };
  const answer = await response.json().catch(() => null) as ExtractAnswer | null;
  if (!answer) return { ok: false, message: 'The receipt could not be read. Enter the values yourself.', retry: false };
  if (!answer.ok) return { ok: false, message: answer.error.message, retry: answer.error.retry };
  return { ok: true, value: answer.draft };
}

export function validateDraft(draft: ReceiptDraft): ReceiptDraftErrors {
  const errors: ReceiptDraftErrors = {};
  if (!draft.merchant.trim()) errors.merchant = 'Add the merchant.';
  if (draft.purchased_on && !/^\d{4}-\d{2}-\d{2}$/.test(draft.purchased_on)) errors.purchased_on = 'Use YYYY-MM-DD, or leave it empty.';
  if (draft.currency && !/^[A-Z]{3}$/.test(draft.currency)) errors.currency = 'Use a three-letter code such as USD, or leave it empty.';
  if (draft.lines.some((line) => !line.description.trim() || !Number.isFinite(line.amount))) errors.lines = 'Every line needs a description and an amount.';
  if (draft.total !== null && !Number.isFinite(draft.total)) errors.total = 'Enter the total as a number, or leave it empty.';
  return errors;
}

/** Refusals the platform answers before writing anything. */
const NOT_WRITTEN = new Set([
  'AUTH_REQUIRED', 'DATA_ACCESS_DENIED', 'DATA_CONTRACT_MISMATCH', 'DATA_IDENTITY_MISMATCH',
  'DATA_INPUT_INVALID', 'DATA_INPUT_TOO_LARGE', 'DATA_OPERATION_INVALID', 'DATA_VALUE_INVALID',
]);

function refusedMessage(code: string): string {
  if (code === 'AUTH_REQUIRED') return 'Your session ended. Sign in again, then save.';
  if (code === 'DATA_CONTRACT_MISMATCH') return 'This app was just updated. Reload the page, then save.';
  return 'The receipt was not saved. Check the values and save again.';
}

/** Saves the reviewed values once and never repeats the write. A lost
 *  response is reported as unknown, not as unsaved. Never calls the model. */
export async function saveReceipt(draft: ReceiptDraft): Promise<SaveOutcome> {
  try {
    const result = await data.receipts.create({
      file_id: draft.file_id,
      merchant: draft.merchant.trim(),
      purchased_on: draft.purchased_on,
      currency: draft.currency,
      total: draft.total,
      lines: draft.lines.map((line) => ({ description: line.description.trim(), amount: line.amount })),
    });
    return { kind: 'saved', message: result.data ? `Saved the receipt from ${result.data.merchant}.` : 'Saved the receipt.' };
  } catch (reason: unknown) {
    const code = reason instanceof DataError ? reason.code : null;
    // One receipt per file (db/schema.ts unique): this file's receipt exists.
    if (code === 'DATA_CONFLICT') return { kind: 'saved', message: 'This receipt is already saved.' };
    if (code && NOT_WRITTEN.has(code)) return { kind: 'refused', message: refusedMessage(code) };
  }
  return { kind: 'unknown', message: 'We could not confirm the save. Check for the saved receipt before saving again.' };
}

/** Read-only: is this file's receipt among the user's saved receipts? */
export async function findSavedReceipt(fileId: string): Promise<SavedCheck> {
  try {
    const page = await data.receipts.list({ where: { file_id: fileId }, limit: 1 });
    const saved = page.data[0];
    return saved ? { kind: 'found', message: `Saved the receipt from ${saved.merchant}.` } : { kind: 'not-found' };
  } catch {
    return { kind: 'unknown', message: 'Could not check right now. Try again in a moment.' };
  }
}
```

### The page flow

```ts
// src/data/useReceiptFlow.ts
import { useEffect, useRef, useState } from 'react';
import type { ReceiptDraft, ReceiptDraftErrors, ReceiptFlowStep } from '../../types/receipts';
import { extractReceipt, findSavedReceipt, saveReceipt, uploadReceipt, validateDraft } from '../services/receipts';

export interface ReceiptFlow {
  step: ReceiptFlowStep;
  /** The last failure, with whether trying the same action again is reasonable. */
  problem: { message: string; retry: boolean } | null;
  errors: ReceiptDraftErrors;
  /** The uploaded file whose reading can be requested again by the user. */
  retryFileId: string | null;
  choose(file: File): Promise<void>;
  extract(fileId: string): Promise<void>;
  enterManually(): void;
  edit(draft: ReceiptDraft): void;
  save(): Promise<void>;
  /** After an unconfirmed save: look for this file's saved receipt (read-only). */
  checkSaved(): Promise<void>;
  startOver(): void;
}

const BLANK = (fileId: string): ReceiptDraft => ({ file_id: fileId, merchant: '', purchased_on: '', currency: '', lines: [], total: null });

// Upload → one extraction → review → explicit save. Editing and saving never
// call the model; a failed reading is only repeated if the user asks.
export function useReceiptFlow(): ReceiptFlow {
  const mounted = useRef(false);
  // Set synchronously, so a second click before React re-renders cannot start
  // a second upload, model call or save.
  const busy = useRef(false);
  const [step, setStep] = useState<ReceiptFlowStep>({ kind: 'choose' });
  const [problem, setProblem] = useState<ReceiptFlow['problem']>(null);
  const [retryFileId, setRetryFileId] = useState<string | null>(null);

  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  async function once(action: () => Promise<void>): Promise<void> {
    if (busy.current) return;
    busy.current = true;
    try {
      await action();
    } finally {
      busy.current = false;
    }
  }

  async function runExtraction(fileId: string) {
    setProblem(null);
    setStep({ kind: 'extracting', fileId });
    const read = await extractReceipt(fileId);
    if (!mounted.current) return;
    if (read.ok) {
      setRetryFileId(null);
      setStep({ kind: 'review', draft: read.value });
    } else {
      setProblem({ message: read.message, retry: read.retry });
      setRetryFileId(fileId);
      setStep({ kind: 'choose' });
    }
  }

  const draft = step.kind === 'review' || step.kind === 'saving' || step.kind === 'unconfirmed' ? step.draft : null;
  const errors = draft ? validateDraft(draft) : {};

  return {
    step,
    problem,
    errors,
    retryFileId,
    choose: (file) => once(async () => {
      setProblem(null);
      setRetryFileId(null);
      setStep({ kind: 'uploading' });
      const uploaded = await uploadReceipt(file);
      if (!mounted.current) return;
      if (!uploaded.ok) {
        setProblem({ message: uploaded.message, retry: uploaded.retry });
        setStep({ kind: 'choose' });
        return;
      }
      await runExtraction(uploaded.value);
    }),
    extract: (fileId) => once(() => runExtraction(fileId)),
    enterManually() {
      if (!retryFileId || busy.current) return;
      setProblem(null);
      setStep({ kind: 'review', draft: BLANK(retryFileId) });
      setRetryFileId(null);
    },
    edit(next) {
      if (step.kind === 'review') setStep({ kind: 'review', draft: next });
    },
    // From review, or again from an unconfirmed save after a look found
    // nothing: a second write of the same file is refused, never duplicated.
    save: () => once(async () => {
      const ready = step.kind === 'review' || (step.kind === 'unconfirmed' && step.checked);
      if (!ready || Object.keys(errors).length > 0) return;
      const reviewed = step.draft;
      setProblem(null);
      setStep({ kind: 'saving', draft: reviewed });
      const saved = await saveReceipt(reviewed);
      if (!mounted.current) return;
      if (saved.kind === 'saved') setStep({ kind: 'saved', message: saved.message });
      else if (saved.kind === 'refused') {
        setProblem({ message: saved.message, retry: true });
        setStep({ kind: 'review', draft: reviewed });
      } else {
        setProblem({ message: saved.message, retry: false });
        setStep({ kind: 'unconfirmed', draft: reviewed, checked: false });
      }
    }),
    checkSaved: () => once(async () => {
      if (step.kind !== 'unconfirmed') return;
      const pending = step.draft;
      const found = await findSavedReceipt(pending.file_id);
      if (!mounted.current) return;
      if (found.kind === 'found') {
        setProblem(null);
        setStep({ kind: 'saved', message: found.message });
      } else if (found.kind === 'not-found') {
        // Absence is not proof the save failed; say what is known.
        setProblem({ message: 'No saved receipt for this file yet. If you just saved, check again in a moment. Saving again is safe: a duplicate is refused.', retry: true });
        setStep({ kind: 'unconfirmed', draft: pending, checked: true });
      } else {
        setProblem({ message: found.message, retry: true });
      }
    }),
    startOver() {
      if (busy.current) return;
      setProblem(null);
      setRetryFileId(null);
      setStep({ kind: 'choose' });
    },
  };
}
