### The review form

```tsx
// src/ui/ReceiptReview.tsx
import type { ChangeEvent, FormEvent } from 'react';
import type { ReceiptDraft, ReceiptLine } from '../../types/receipts';
import type { ReceiptFlow } from '../data/useReceiptFlow';
import { RECEIPT_TYPES } from '../services/receipts';

/** An empty field is NaN, which validation reports, never a silent 0. */
const amountOf = (value: string): number => (value.trim() === '' ? Number.NaN : Number(value));

export function ReceiptReview({ flow }: { flow: ReceiptFlow }) {
  const { step, problem } = flow;
  return (
    <div className="panel">
      <h1 className="panel__title">Receipts</h1>
      {step.kind === 'choose' ? <ChooseFile flow={flow} /> : null}
      {step.kind === 'uploading' ? <p role="status">Uploading…</p> : null}
      {step.kind === 'extracting' ? <p role="status">Reading the receipt…</p> : null}
      {step.kind === 'review' || step.kind === 'saving' ? <ReviewForm flow={flow} draft={step.draft} saving={step.kind === 'saving'} /> : null}
      {step.kind === 'unconfirmed' ? (
        <div className="actions">
          <p role="status">Saving {step.draft.merchant || 'this receipt'} was not confirmed.</p>
          <button type="button" className="button" onClick={() => void flow.checkSaved()}>Check saved receipt</button>
          {step.checked ? <button type="button" className="button button--quiet" onClick={() => void flow.save()}>Save again</button> : null}
        </div>
      ) : null}
      {step.kind === 'saved' ? (
        <div className="actions">
          <p role="status">{step.message}</p>
          <button type="button" className="button" onClick={flow.startOver}>Add another receipt</button>
        </div>
      ) : null}
      {problem ? <p className="notice error" role="alert">{problem.message}</p> : null}
    </div>
  );
}

function ChooseFile({ flow }: { flow: ReceiptFlow }) {
  function onChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (file) void flow.choose(file);
  }
  const fileId = flow.retryFileId;
  return (
    <>
      <div className="field">
        <label htmlFor="receipt-file">Receipt photo or PDF <span className="hint">up to 5 MB</span></label>
        <input id="receipt-file" type="file" accept={RECEIPT_TYPES.join(',')} onChange={onChange} />
      </div>
      {fileId ? (
        <div className="actions">
          <button type="button" className="button button--quiet" onClick={flow.enterManually}>Enter the values myself</button>
          {flow.problem?.retry ? <button type="button" className="button" onClick={() => void flow.extract(fileId)}>Read it again</button> : null}
        </div>
      ) : null}
    </>
  );
}

function ReviewForm({ flow, draft, saving }: { flow: ReceiptFlow; draft: ReceiptDraft; saving: boolean }) {
  const { errors } = flow;
  const set = (patch: Partial<ReceiptDraft>) => flow.edit({ ...draft, ...patch });
  const setLine = (index: number, patch: Partial<ReceiptLine>) =>
    set({ lines: draft.lines.map((line, i) => (i === index ? { ...line, ...patch } : line)) });

  function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    void flow.save();
  }

  return (
    <form onSubmit={onSubmit} noValidate>
      <p className="muted">Check every value. Nothing is saved until you press Save.</p>
      <div className="field">
        <label htmlFor="receipt-merchant">Merchant</label>
        <input id="receipt-merchant" value={draft.merchant} disabled={saving} onChange={(e) => set({ merchant: e.target.value })} />
        {errors.merchant ? <p className="error">{errors.merchant}</p> : null}
      </div>
      <div className="field">
        <label htmlFor="receipt-date">Date <span className="hint">YYYY-MM-DD</span></label>
        <input id="receipt-date" value={draft.purchased_on} disabled={saving} onChange={(e) => set({ purchased_on: e.target.value.trim() })} />
        {errors.purchased_on ? <p className="error">{errors.purchased_on}</p> : null}
      </div>
      <div className="field">
        <label htmlFor="receipt-currency">Currency</label>
        <input id="receipt-currency" value={draft.currency} disabled={saving} onChange={(e) => set({ currency: e.target.value.trim().toUpperCase() })} />
        {errors.currency ? <p className="error">{errors.currency}</p> : null}
      </div>
      <fieldset className="field" disabled={saving}>
        <legend>Items</legend>
        {draft.lines.map((line, index) => (
          <div className="actions" key={index}>
            <input aria-label={`Item ${index + 1}`} value={line.description} onChange={(e) => setLine(index, { description: e.target.value })} />
            <input aria-label={`Amount ${index + 1}`} type="number" step="0.01" value={Number.isNaN(line.amount) ? '' : line.amount}
              onChange={(e) => setLine(index, { amount: amountOf(e.target.value) })} />
            <button type="button" className="link-button link-button--danger" onClick={() => set({ lines: draft.lines.filter((_, i) => i !== index) })}>Remove</button>
          </div>
        ))}
        <button type="button" className="link-button" onClick={() => set({ lines: [...draft.lines, { description: '', amount: Number.NaN }] })}>Add item</button>
        {errors.lines ? <p className="error">{errors.lines}</p> : null}
      </fieldset>
      <div className="field">
        <label htmlFor="receipt-total">Total</label>
        <input id="receipt-total" type="number" step="0.01" disabled={saving} value={draft.total === null || Number.isNaN(draft.total) ? '' : draft.total}
          onChange={(e) => set({ total: e.target.value.trim() === '' ? null : amountOf(e.target.value) })} />
        {errors.total ? <p className="error">{errors.total}</p> : null}
      </div>
      <div className="actions">
        <button type="submit" className="button" disabled={saving || Object.keys(errors).length > 0} aria-busy={saving}>{saving ? 'Saving…' : 'Save'}</button>
        <button type="button" className="button button--quiet" disabled={saving} onClick={flow.startOver}>Discard</button>
      </div>
    </form>
  );
}
